const DIGEST_PREFIX: &str = "# velnor-gen-sha256: ";
pub const VELNOR_GEN_MARKER: &str = "# Generated by velnor-gen.";
const ENGINE_MARKERS: [&str; 2] = [
    "# Generated by Velnor Actions ",
    "# Generated by velnor-actions ",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Owner {
    VelnorGen,
    /// Claims the velnor-gen marker but its content digest does not verify.
    Forged,
    Engine,
    Nobody,
}

/// Header line, digest line binding the body, then the body.
#[must_use]
pub fn seal(header: &str, body: &str) -> String {
    format!("{header}{DIGEST_PREFIX}{}\n{body}", digest(body.as_bytes()))
}

fn digest(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    Sha256::digest(bytes)
        .iter()
        .flat_map(|byte| [byte >> 4, byte & 15])
        .filter_map(|nibble| char::from_digit(u32::from(nibble), 16))
        .collect()
}

fn digest_verifies(contents: &[u8]) -> bool {
    let mut lines = contents.splitn(3, |byte| *byte == b'\n');
    let (_, Some(second), body) = (lines.next(), lines.next(), lines.next().unwrap_or_default())
    else {
        return false;
    };
    second
        .strip_prefix(DIGEST_PREFIX.as_bytes())
        .is_some_and(|hex| hex == digest(body).as_bytes())
}

#[must_use]
pub fn owner_of(contents: &[u8]) -> Owner {
    let first = contents
        .split(|byte| *byte == b'\n')
        .next()
        .unwrap_or_default();
    let first = first.strip_suffix(b"\r").unwrap_or(first);
    if let Some(rest) = first.strip_prefix(VELNOR_GEN_MARKER.as_bytes())
        && (rest.is_empty() || rest.starts_with(b" "))
    {
        if digest_verifies(contents) {
            Owner::VelnorGen
        } else {
            Owner::Forged
        }
    } else if ENGINE_MARKERS
        .iter()
        .any(|marker| first.starts_with(marker.as_bytes()))
    {
        Owner::Engine
    } else {
        Owner::Nobody
    }
}
